package data_structures.trees;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class AVLTree {
public static class Tree<T> implements Iterable<T>{private static class Node<T>{T value;Node<T> left,right;int height=1;Node(T v){value=v;}}private Node<T> root;private int count;private final Comparator<T> compare;public Tree(){this(shared.Compare::defaultCompare);}public Tree(Comparator<T> c){compare=c;}public int size(){return count;}private int h(Node<T> n){return n==null?0:n.height;}public int height(){return h(root);}private int balance(Node<T> n){return h(n.left)-h(n.right);}private void refresh(Node<T> n){n.height=1+Math.max(h(n.left),h(n.right));}private Node<T> right(Node<T> n){Node<T> p=n.left;n.left=p.right;p.right=n;refresh(n);refresh(p);return p;}private Node<T> left(Node<T> n){Node<T> p=n.right;n.right=p.left;p.left=n;refresh(n);refresh(p);return p;}private Node<T> rebalance(Node<T> n){refresh(n);int b=balance(n);if(b>1){if(balance(n.left)<0)n.left=left(n.left);return right(n);}if(b< -1){if(balance(n.right)>0)n.right=right(n.right);return left(n);}return n;}public boolean has(T v){Node<T> n=root;while(n!=null){int c=compare.compare(v,n.value);if(c==0)return true;n=c<0?n.left:n.right;}return false;}public boolean insert(T v){if(has(v))return false;root=insert(root,v);count++;return true;}private Node<T> insert(Node<T> n,T v){if(n==null)return new Node<>(v);if(compare.compare(v,n.value)<0)n.left=insert(n.left,v);else n.right=insert(n.right,v);return rebalance(n);}public boolean delete(T v){if(!has(v))return false;root=remove(root,v);count--;return true;}private Node<T> remove(Node<T> n,T v){if(n==null)return null;int c=compare.compare(v,n.value);if(c<0)n.left=remove(n.left,v);else if(c>0)n.right=remove(n.right,v);else{if(n.left==null||n.right==null)return n.left!=null?n.left:n.right;Node<T> s=n.right;while(s.left!=null)s=s.left;n.value=s.value;n.right=remove(n.right,s.value);}return rebalance(n);}public boolean isBalanced(){return check(root);}private boolean check(Node<T> n){return n==null||Math.abs(balance(n))<=1&&check(n.left)&&check(n.right);}public List<T> toArray(){List<T> o=new ArrayList<>();walk(root,o);return o;}private void walk(Node<T> n,List<T> o){if(n!=null){walk(n.left,o);o.add(n.value);walk(n.right,o);}}public Iterator<T> iterator(){return toArray().iterator();}}
}
